// Executed directly from the user's tap so the phone can ask for GPS permission.
const w=typeof window!=='undefined'?window:null;
if(!w?.isSecureContext) return {granted:false,reason:'secure'};
if(!w.navigator?.geolocation) return {granted:false,reason:'unsupported'};
try {
  const p=await new Promise((resolve,reject)=>{
    w.navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:false,timeout:20000,maximumAge:120000});
  });
  return {granted:true,lat:Number(p.coords.latitude.toFixed(3)),lon:Number(p.coords.longitude.toFixed(3))};
}catch(e){return {granted:false,reason:e?.code===1?'denied':e?.code===2?'unavailable':e?.code===3?'timeout':'error'};}

