// Use the browser's geolocation API on iPhone and Android Chrome.
const browserWindow = (typeof window !== 'undefined' ? window : (typeof wwLib !== 'undefined' && wwLib.getFrontWindow ? wwLib.getFrontWindow() : null));
const nav = browserWindow?.navigator;
if (!browserWindow?.isSecureContext) return { granted:false,reason:'secure' };
if (!nav?.geolocation) return { granted:false,reason:'unsupported' };
try {
  const position=await new Promise((resolve,reject)=>nav.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:false,timeout:20000,maximumAge:600000}));
  return { granted:true,lat:Number(position.coords.latitude.toFixed(3)),lon:Number(position.coords.longitude.toFixed(3)) };
} catch(error) {
  return { granted:false,reason:error?.code===1?'denied':error?.code===2?'unavailable':error?.code===3?'timeout':'unknown' };
}

