// Compute current season from today's date without fabricating weather values
const month = new Date().getMonth() + 1;
let season = 'Vinter';
if (month >= 3 && month <= 5) season = 'Vår';
else if (month >= 6 && month <= 8) season = 'Sommer';
else if (month >= 9 && month <= 11) season = 'Høst';
return {
  available: false,
  locationName: context.parameters['locationName'] || '',
